import {initial,localDay,uid,balance,checkHabit,redeem,addEntry,fulfill,cancel} from './model.js';
const KEY='little-habit-garden-v1';
let state,storageError=false;
try{const saved=localStorage.getItem(KEY);state=saved?JSON.parse(saved):initial();if(state.version!==1||!Array.isArray(state.ledger)||!Array.isArray(state.habits))throw Error();}catch{state=initial();storageError=true;}
let page='today',filter='全部习惯',ledgerFilter='全部',parent=false,menu=false,day=localDay(),modalClose=null;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={leaf:'<path d="M19 3C9 2 3 6 4 13s9 8 13 2c3-5 2-12 2-12Z"/><path d="m4 21 9-12M8 16l-1-5m1 5 6-1"/>',home:'<path d="m3 10 9-7 9 7v10H4V10m5 10v-7h6v7"/>',gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13"/><path d="M12 8C2 8 5 0 9 3l3 5c10 0 7-8 3-5Z"/>',chart:'<path d="M4 3v18h17M9 16v-5m5 5V6m5 10v-8"/>',book:'<path d="M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Zm0 0v16"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'};
const icon=n=>`<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.leaf}</svg>`;
const btn=(label,action,cls='outline',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const total=()=>balance(state);
const completed=()=>state.habits.filter(h=>state.checks.some(c=>c.day===day&&c.habitId===h.id)).length;
const earnedToday=()=>state.ledger.filter(e=>e.amount>0&&e.kind!=='refund'&&localDay(new Date(e.at))===day).reduce((n,e)=>n+e.amount,0);
const streak=()=>{let d=new Date();let n=0;const days=new Set(state.checks.map(c=>c.day));if(!days.has(localDay(d)))d.setDate(d.getDate()-1);while(days.has(localDay(d))){n++;d.setDate(d.getDate()-1)}return n;};
const dateText=()=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
const timeText=s=>new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(s));
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('toast-show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('toast-show'),3300)}
function commit(change){const next=structuredClone(state);change(next);try{localStorage.setItem(KEY,JSON.stringify(next))}catch{throw Error('保存失败，请检查浏览器存储空间后重试。此次操作未生效。')}state=next;render();}
const garden=`<svg class="garden-art" viewBox="0 0 280 250" fill="none" aria-hidden="true"><ellipse cx="157" cy="234" rx="117" ry="16" fill="#dee7cf"/><path d="M143 221c3-40 1-78 6-120" stroke="#a6a278" stroke-width="13" stroke-linecap="round"/><path d="m147 168-33-33m35 13 30-29" stroke="#a6a278" stroke-width="8" stroke-linecap="round"/><path d="M100 144c-34 1-44-23-29-43-20-22-3-47 20-50-1-25 29-38 48-23 20-19 50-10 54 13 28-4 43 23 34 43 28 24 11 55-18 56-10 28-48 27-61 7-15 14-36 12-48-3Z" fill="#c2d1a1"/><path d="M100 144c-34 1-44-23-29-43-20-22-3-47 20-50-1-25 29-38 48-23 20-19 50-10 54 13 28-4 43 23 34 43-13-11-33-13-45-5-22-26-62-17-66 11-25 7-31 32-16 54Z" fill="#d1ddba"/><path d="M176 159c-13 6-27-2-28-12-15 14-36 12-48-3 20-12 42-9 48-25 11-28 41-23 57-13 8 19-5 41-29 53Z" fill="#b4c693"/><circle cx="93" cy="96" r="7" fill="#e2b582"/><circle cx="182" cy="59" r="7" fill="#e8c193"/><circle cx="192" cy="116" r="7" fill="#dea779"/><path d="m91 88 1-5m88-32 3-5m9 62 2-5" stroke="#8d9d70" stroke-width="2" stroke-linecap="round"/><path d="M135 225h29" stroke="#9b9b75" stroke-width="4" stroke-linecap="round"/><path d="M70 232v-17m0 10c-13 0-18-10-13-12 8-2 13 8 13 12Zm0-7c1-14 13-20 16-15 3 8-7 14-16 15Z" fill="#a1b582" stroke="#a1b582" stroke-width="2"/><path d="M215 233v-12m0 8c-11-1-12-10-7-11 4-1 7 7 7 11Zm0-4c2-10 11-13 13-9 2 6-7 9-13 9Z" fill="#a9bb8e" stroke="#a9bb8e" stroke-width="2"/><circle cx="239" cy="54" r="4" fill="#e5d2a0"/><path d="m44 60 3 4-3 4-3-4 3-4Z" fill="#b9c9a1"/><path d="m240 158 3 4-3 4-3-4 3-4Z" fill="#b9c9a1"/><path d="M34 144c6-8 12-5 9 1-5 8-11-3-15 1" stroke="#cebb8a" stroke-width="2" stroke-linecap="round"/></svg>`;
function render(){day=localDay();const titles={today:'今日习惯',shop:'心愿商店',ledger:'积分明细',orders:'兑换记录',parent:'家长管理'};const pending=state.orders.filter(o=>o.status==='pending').length;
$('#app').innerHTML=`<div class="mobile-scrim ${menu?'open':''}" data-action="menu"></div><aside class="sidebar ${menu?'open':''}"><div class="brand"><div class="brand-mark">${icon('leaf')}</div><div><strong>小小成长家</strong><small>LITTLE HABIT GARDEN</small></div></div><div class="nav-label">每一天，都在成长</div><nav class="nav" aria-label="主导航">${[['today','home','今日习惯'],['shop','gift','心愿商店'],['ledger','chart','积分明细'],['orders','book','兑换记录']].map(([id,i,name])=>btn(`${icon(i)}${name}${id==='orders'&&pending?`<span class="badge">${pending}</span>`:''}`,'nav',page===id?'active':'',`data-page="${id}" ${page===id?'aria-current="page"':''}`)).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-quote"><span>🌱</span><p>好习惯，是送给未来的礼物。<br>慢慢来，每一天都算数。</p></div>${btn(`${icon('shield')}家长管理${icon('arrow')}`,'nav','parent-button',`data-page="parent"`)}</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${btn(icon('menu'),'menu','menu-toggle','aria-label="打开菜单"')}${icon('home')}我的成长花园 <span>/</span> <span>${titles[page]}</span></div><div class="topright"><span class="date-label">${dateText()}</span><button class="profile" data-action="profile" aria-label="修改孩子昵称和头像"><span class="avatar">${esc(state.avatar)}</span><div>${esc(state.name)}<small>${parent?'家长管理已解锁':'每天进步一点点'}</small></div></button></div></header>${page==='today'?todayPage():page==='shop'?shopPage():page==='ledger'?ledgerPage():page==='orders'?ordersPage():parentPage()}<footer class="footer">${icon('leaf')} 用陪伴浇灌，让好习惯慢慢发芽</footer></main>`;
}
function welcome(eyebrow,title,subtitle,action=''){return `<section class="welcome"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</section>`}
function wallet(){return `<section class="wallet"><div class="wallet-title"><span class="coin-mini">✧</span> 我的积分小金库</div><div class="wallet-value">${total().toLocaleString()}<span>积分</span></div><div class="coin-art">✦</div><div class="wallet-note">每一份努力，都值得被看见</div><div class="wallet-divider"></div><div class="wallet-bottom"><span>可兑换现金 ¥${total().toLocaleString()}</span>${btn('去兑换 →','nav','text-button','data-page="shop"')}</div></section>`}
function todayPage(){const count=completed(),all=state.habits.length;const habits=state.habits.filter(h=>filter==='全部习惯'||h.category===filter);return `${welcome('A LITTLE BETTER, EVERY DAY',`${esc(state.name)}，今天也一起加油 <span style="font-size:21px">☀️</span>`,'把小小的坚持，变成大大的成长。',btn(`${icon('plus')} 添加习惯`,'add-habit'))}<div class="hero-grid"><section class="garden-banner"><div class="garden-copy"><span class="pill">🌱 我的习惯成长计划</span><h2>每一个好习惯，<br>都是一颗成长的种子。</h2><p>${count===all&&all?'今天的任务全部完成啦，给自己一个拥抱！':'完成今天的小任务，让你的成长树再长大一点。'}</p><div class="progress-row"><div class="progress-track" role="progressbar" aria-label="今日完成进度" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="${all||1}"><i style="width:${all?count/all*100:0}%"></i></div><span>今日已完成 ${count} / ${all}</span></div></div>${garden}</section>${wallet()}</div><section class="stats"><div class="stat"><div class="stat-icon">☀️</div><div><div class="stat-label">今日获得</div><div class="stat-number">+${earnedToday()}<small>积分</small></div></div><span class="stat-tip">努力正在发光</span></div><div class="stat"><div class="stat-icon">🌿</div><div><div class="stat-label">连续坚持</div><div class="stat-number">${streak()}<small>天</small></div></div><span class="stat-tip">每天一点点</span></div><div class="stat"><div class="stat-icon">🏅</div><div><div class="stat-label">累计完成</div><div class="stat-number">${state.checks.length}<small>次好习惯</small></div></div><span class="stat-tip">为自己鼓掌</span></div></section><div class="content-grid"><section><div class="section-heading"><h2>今日习惯 <small>TODAY’S HABITS</small></h2>${btn('管理习惯 ↗','manage-habits','text-button')}</div><div class="tabs" role="group" aria-label="筛选习惯">${['全部习惯','学习成长','家务劳动','生活习惯'].map(f=>btn(f,'filter',filter===f?'selected':'',`data-filter="${f}" aria-pressed="${filter===f}"`)).join('')}</div><div class="habit-list">${habits.length?habits.map(habitRow).join(''):'<div class="empty"><span>🌱</span>还没有这类习惯，种下第一颗种子吧。</div>'}</div></section><aside class="side-column"><div class="section-heading"><h2>小小心愿</h2>${btn('全部奖励 →','nav','text-button','data-page="shop"')}</div><div class="reward-box">${state.rewards.slice(0,3).map(r=>`<div class="reward-mini"><div class="reward-mini-icon">${esc(r.icon)}</div><div class="reward-mini-info"><strong>${esc(r.name)}</strong><small>✧ ${r.type==='cash'?'1 积分 = ¥1':r.cost+' 积分'}</small></div>${btn('兑换','redeem','',`data-id="${r.id}"`)}</div>`).join('')||'<div class="empty">家长可以添加你的心愿奖励</div>'}<div class="cash-note">💛 每个心愿，都有家长的爱来兑现。<br>现金兑换比例为 1 积分 = 1 元。</div></div>${weekly()}</aside></div>`}
function habitRow(h){const done=state.checks.some(c=>c.habitId===h.id&&c.day===day);return `<article class="habit ${done?'done':''}"><div class="habit-emoji">${esc(h.icon)}</div><div class="habit-info"><div class="habit-name">${esc(h.name)}</div><div class="habit-sub">${esc(h.note||h.category)}</div></div><span class="habit-points">+${h.points} ✧</span>${btn(done?'✓ 已完成':'打卡 +','check',`check-button ${done?'done':''}`,`data-id="${h.id}" ${done?'disabled':''} aria-label="${esc(h.name)}：${done?'今日已完成':'打卡获得'+h.points+'积分'}"`)}</article>`}
function weekly(){const now=new Date(),weekday=(now.getDay()+6)%7;return `<div class="weekly"><h3>本周的小坚持 <span>${state.checks.filter(c=>{const d=new Date(c.day+'T12:00:00');const start=new Date();start.setDate(now.getDate()-weekday);start.setHours(0,0,0,0);return d>=start&&c.day<=localDay(now)}).length} 次打卡</span></h3><div class="week-dots">${['一','二','三','四','五','六','日'].map((n,i)=>{const d=new Date();d.setDate(now.getDate()-weekday+i);const checked=state.checks.some(c=>c.day===localDay(d));return `<div class="week-day">${n}<div class="week-dot ${checked?'complete':''} ${i===weekday?'today':''}">${checked?'✓':i===weekday?'·':''}</div></div>`}).join('')}</div><p>不着急、不比较，走好自己的每一步。</p></div>`}
function shopPage(){return `${welcome('LITTLE WISHES, BIG MOTIVATION','心愿商店 🎁','用一点点努力，兑换一份属于自己的快乐。',btn(`${icon('plus')} 添加奖励`,'add-reward'))}<div class="notice">我的积分 <strong>${total()}</strong> ✧　｜　现金 1 积分 = 1 元　·　兑换后扣除积分，由家长支付或兑现</div><div class="shop-grid">${state.rewards.map(r=>`<article class="reward-card"><div class="reward-visual">${esc(r.icon)}</div><h3>${esc(r.name)}</h3><p>${esc(r.note||'用努力兑换小小的美好')}</p><div class="reward-bottom"><span>✧ ${r.type==='cash'?'1 积分 / 元':r.cost+' 积分'}</span>${btn('兑换心愿','redeem','primary',`data-id="${r.id}"`)}</div></article>`).join('')||'<div class="empty">还没有奖励，添加第一个心愿吧。</div>'}</div>`}
function ledgerPage(){const records=state.ledger.filter(e=>ledgerFilter==='全部'||(ledgerFilter==='收入'?e.amount>0:e.amount<0));return `${welcome('EVERY EFFORT COUNTS','积分明细','每一份付出、每一次奖励，都有迹可循。',btn('± 调整积分','adjust'))}<div class="hero-grid">${wallet()}<section class="garden-banner" style="min-height:180px"><span class="eyebrow">成长，是一场温柔的积累</span><h2 style="font-size:24px;font-weight:500">认真做的小事<br>也值得被好好记录。</h2></section></div><section class="panel"><div class="section-heading"><h2>积分账本</h2><div class="tabs" style="margin:0">${['全部','收入','支出'].map(f=>btn(f,'ledger-filter',ledgerFilter===f?'selected':'',`data-filter="${f}"`)).join('')}</div></div>${records.length?records.map(e=>`<div class="record"><div class="record-icon">${e.kind==='habit'?'🌱':e.kind==='redeem'?'🎁':e.kind==='refund'?'↩️':e.amount>0?'⭐':'📝'}</div><div class="record-info"><strong>${esc(e.title)}</strong><small>${timeText(e.at)} · ${{habit:'习惯打卡',redeem:'奖励兑换',adjust:'家长调整',refund:'取消退回'}[e.kind]||'积分变动'}</small></div><div class="amount ${e.amount<0?'negative':''}">${e.amount>0?'+':''}${e.amount}</div></div>`).join(''):'<div class="empty"><span>📒</span>还没有积分记录<br>完成一个好习惯，记录第一份努力吧。</div>'}</section>`}
function ordersPage(){return `${welcome('HAPPINESS IS ON THE WAY','兑换记录','每一个小心愿，都值得认真兑现。',parent?btn('锁定家长管理','lock'):btn(`${icon('shield')} 家长确认兑现`,'unlock'))}<div class="notice">兑换时已扣除积分。现金由家长自行支付，支付后点击“确认已支付”；其他奖励在完成后确认兑现。</div><section class="panel"><h2>我的心愿清单</h2>${state.orders.length?state.orders.map(o=>`<div class="record"><div class="record-icon">${esc(o.icon)}</div><div class="record-info"><strong>${esc(o.title)}</strong><small>${timeText(o.at)} · ${o.cost} 积分${o.type==='cash'?` · 家长支付 ¥${o.cost}`:''}${o.fulfilledAt?` · ${timeText(o.fulfilledAt)} 已兑现`:''}</small></div><span class="status ${o.status}">${{pending:'待家长兑现',fulfilled:'已兑现',cancelled:'已取消 · 积分已退回'}[o.status]}</span>${o.status==='pending'&&parent?`<div class="actions">${btn(o.type==='cash'?'确认已支付':'确认已兑现','fulfill','primary',`data-id="${o.id}"`)}${btn('取消并退分','cancel-order','outline',`data-id="${o.id}"`)}</div>`:''}</div>`).join(''):'<div class="empty"><span>🎁</span>心愿清单还是空的<br>去心愿商店挑选一份喜欢的奖励吧。</div>'}</section>`}
function parentPage(){if(!parent)return `${welcome('GROW TOGETHER','家长管理','陪伴、鼓励，一起见证每一个小进步。')}<section class="panel lock-panel"><span>🌳</span><h2>给成长多一点陪伴</h2><p>在这里设置习惯和奖励、加减积分，确认兑现孩子的心愿。<br>${state.pin?'输入家长口令，即可进入管理。':'首次使用，请设置一个至少 4 位的家长口令。'}</p>${btn(state.pin?'解锁家长管理':'设置家长口令','unlock','primary')}</section><div class="notice" style="margin-top:22px">数据保存在当前浏览器。家长口令用于日常操作区分，不属于账户级安全保护；请在解锁后导出备份。</div>`;
return `${welcome('GROW TOGETHER','家长管理 🌳','好习惯需要鼓励，也需要清晰、温柔的约定。',`<div class="actions">${btn('± 调整积分','adjust','primary')}${btn('锁定','lock')}</div>`)}<div class="notice">${state.orders.filter(o=>o.status==='pending').length} 个心愿等待兑现。 ${btn('查看兑换记录 →','nav','text-button','data-page="orders"')} <span class="admin-tag">家长模式已解锁 · 关闭或刷新页面后自动锁定</span></div><div class="settings-grid"><section class="panel admin-list"><div class="section-heading"><h2>习惯管理</h2>${btn('+ 添加','add-habit','text-button')}</div>${state.habits.map(h=>`<div class="record"><div class="record-icon">${esc(h.icon)}</div><div class="record-info"><strong>${esc(h.name)}</strong><small>${esc(h.category)} · 每日 +${h.points} 积分</small></div><div class="actions">${btn('编辑','edit-habit','text-button',`data-id="${h.id}"`)}${btn('删除','delete-habit','text-button',`data-id="${h.id}"`)}</div></div>`).join('')}</section><section class="panel admin-list"><div class="section-heading"><h2>奖励管理</h2>${btn('+ 添加','add-reward','text-button')}</div>${state.rewards.map(r=>`<div class="record"><div class="record-icon">${esc(r.icon)}</div><div class="record-info"><strong>${esc(r.name)}</strong><small>${r.type==='cash'?'现金 · 1 积分 = 1 元':r.cost+' 积分'}</small></div><div class="actions">${btn('编辑','edit-reward','text-button',`data-id="${r.id}"`)}${btn('删除','delete-reward','text-button',`data-id="${r.id}"`)}</div></div>`).join('')}</section></div><section class="panel"><div class="section-heading"><h2>家庭设置与数据</h2></div><div class="actions">${btn('修改昵称和头像','profile')}${btn('修改家长口令','change-pin')}${btn('导出数据备份','export')}${btn('导入备份','import')}</div><p class="field-help">数据仅保存在当前浏览器，不会跨设备自动同步。清理浏览器数据会清空记录，建议定期导出备份。现金支付在线下由家长完成。</p></section>`}
function closeModal(){const focus=modalClose;$('#modal-root').innerHTML='';document.body.style.overflow='';modalClose=null;focus?.focus();}
function modal(title,content,onSubmit){modalClose=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><form id="modal-form">${content}<div class="error" role="alert" id="form-error"></div></form></section></div>`;document.body.style.overflow='hidden';$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();try{await onSubmit(new FormData(e.target))}catch(error){if($('#form-error'))$('#form-error').textContent=error.message;else toast(error.message)}});setTimeout(()=>$('#modal-root input, #modal-root select, #modal-root .primary, #modal-root .close')?.focus(),40);}
const field=(label,name,value='',type='text',attrs='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
const submit=(s='保存')=>`<button class="primary full" type="submit">${s}</button>`;
const emojiField=(value)=>`<div class="field"><label for="f-icon">选择图标，也可以输入喜欢的 emoji</label><div class="emoji-picker">${['📖','✏️','🧹','🛏️','🪥','⚽','🍦','📺','💰','🎨','🎹','🧒'].map(e=>`<button type="button" data-action="emoji" data-emoji="${e}" aria-label="选择 ${e}">${e}</button>`).join('')}</div><input id="f-icon" name="icon" value="${esc(value)}" maxlength="16" required aria-label="自定义图标"></div>`;
async function hash(s,salt){const data=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+':'+s));return Array.from(new Uint8Array(data),v=>v.toString(16).padStart(2,'0')).join('')}
function guard(next){if(parent)return next();pinModal(next)}
function pinModal(next=()=>render(),changing=false){const setup=!state.pin;modal(changing?'修改家长口令':setup?'设置家长口令':'家长管理验证',`<p>${setup?'设置至少 4 位口令，用于管理习惯、调整积分和确认兑现。请妥善记住口令。':'请输入家长口令，继续这次操作。'}</p>${!setup?field(changing?'当前口令':'家长口令','pin','','password','required autocomplete="current-password"'):''}${setup||changing?`${field('新口令','newPin','','password','required minlength="4" maxlength="64" autocomplete="new-password"')}${field('再次输入','repeat','','password','required minlength="4" maxlength="64" autocomplete="new-password"')}`:''}${submit(setup?'设置并继续':'确认')}`,async f=>{if(!setup&&(await hash(f.get('pin'),state.pin.salt))!==state.pin.hash)throw Error('口令不正确，请重新输入');if(setup||changing){const raw=f.get('newPin');if(raw.trim().length<4)throw Error('口令至少 4 位');if(raw!==f.get('repeat'))throw Error('两次口令不一致');const salt=uid(),value=await hash(raw,salt);commit(s=>s.pin={salt,hash:value});}parent=true;closeModal();render();next();});}
function editHabit(id){guard(()=>{const h=state.habits.find(h=>h.id===id)||{name:'',icon:'📖',category:'学习成长',points:5,note:''};modal(id?'编辑习惯':'种下一个新习惯',`${field('习惯名称','name',h.name,'text','required maxlength="30" placeholder="例如：每天练琴 15 分钟"')}${emojiField(h.icon)}<div class="field-row"><div class="field"><label for="f-category">习惯分类</label><select name="category" id="f-category">${['学习成长','家务劳动','生活习惯'].map(c=>`<option ${h.category===c?'selected':''}>${c}</option>`).join('')}</select></div>${field('每日完成奖励 / 积分','points',h.points,'number','required min="1" max="1000000" step="1"')}</div>${field('一句小鼓励（选填）','note',h.note,'text','maxlength="60" placeholder="每一个小进步，都值得表扬"')}<p>每天可完成一次。编辑积分只影响之后的打卡。</p>${submit(id?'保存修改':'添加习惯')}`,f=>{const name=f.get('name').trim(),emoji=f.get('icon').trim(),points=Number(f.get('points'));if(!name||!emoji)throw Error('请填写名称和图标');if(!Number.isSafeInteger(points)||points<1||points>1000000)throw Error('请填写有效的正整数积分');commit(s=>{const data={id:id||uid(),name,icon:emoji,category:f.get('category'),points,note:f.get('note').trim()};if(id)s.habits[s.habits.findIndex(x=>x.id===id)]=data;else s.habits.push(data)});closeModal();toast(id?'习惯已更新':'新的成长种子，种好啦 🌱');});})}
function editReward(id){guard(()=>{const r=state.rewards.find(r=>r.id===id)||{name:'',icon:'🎁',type:'reward',cost:20,note:''};modal(id?'编辑心愿奖励':'添加心愿奖励',`${field('奖励名称','name',r.name,'text','required maxlength="30" placeholder="例如：一次亲子电影"')}${emojiField(r.icon)}<div class="field-row"><div class="field"><label for="f-type">兑换类型</label><select name="type" id="f-type"><option value="reward" ${r.type==='reward'?'selected':''}>实物 / 活动奖励</option><option value="cash" ${r.type==='cash'?'selected':''}>现金（1 积分 = 1 元）</option></select></div>${field('所需积分 / 默认现金金额','cost',r.cost,'number','required min="1" max="1000000" step="1"')}</div>${field('奖励说明（选填）','note',r.note,'text','maxlength="60"')}<p>现金奖励兑换时可自选金额，积分与人民币始终 1:1，不会自动付款。</p>${submit(id?'保存修改':'添加奖励')}`,f=>{const name=f.get('name').trim(),emoji=f.get('icon').trim(),cost=Number(f.get('cost'));if(!name||!emoji)throw Error('请填写名称和图标');if(!Number.isSafeInteger(cost)||cost<1||cost>1000000)throw Error('请填写有效的正整数积分');commit(s=>{const data={id:id||uid(),name,icon:emoji,type:f.get('type'),cost,note:f.get('note').trim()};if(id)s.rewards[s.rewards.findIndex(x=>x.id===id)]=data;else s.rewards.push(data)});closeModal();toast('心愿奖励已保存 🎁')});})}
function redeemModal(id){const r=state.rewards.find(r=>r.id===id);if(!r)return;modal('兑换一个小心愿',`<div class="modal-summary"><div class="big-emoji">${esc(r.icon)}</div><h3>${esc(r.name)}</h3><strong>${r.type==='cash'?'1 积分 = 1 元':r.cost+' 积分'}</strong><p>当前可用 ${total()} 积分</p></div>${r.type==='cash'?field('兑换现金金额 / 元','cash',r.cost,'number','required min="1" max="1000000" step="1"'):''}<p>确认后立即扣除积分，生成待兑现记录。${r.type==='cash'?'现金由家长自行支付。':'请家长为你兑现奖励。'}</p>${submit('确认兑换')}`,f=>{let cost;commit(s=>{cost=redeem(s,id,Number(f.get('cash'))).cost});closeModal();toast(`兑换成功，已扣除 ${cost} 积分，等待家长兑现 🎁`)});}
function adjustModal(){guard(()=>modal('调整成长积分',`<p>及时鼓励，也温柔地提醒。每次调整都会记入积分账本。</p><div class="field-row"><div class="field"><label for="f-direction">调整方式</label><select id="f-direction" name="direction"><option value="1">奖励加分 ＋</option><option value="-1">提醒减分 −</option></select></div>${field('积分数量','amount',5,'number','required min="1" max="1000000" step="1"')}</div>${field('调整原因','reason','','text','required maxlength="80" placeholder="例如：主动帮助家人"')}<p>当前余额：${total()} 积分。减分后余额不能低于 0。</p>${submit('确认调整')}`,f=>{const reason=f.get('reason').trim();if(!reason)throw Error('请填写调整原因');commit(s=>addEntry(s,Number(f.get('amount'))*Number(f.get('direction')),reason,'adjust'));closeModal();toast('积分已调整，记录已保存');}));}
function confirmModal(title,message,action,label='确认'){modal(title,`<p>${message}</p>${submit(label)}`,()=>{action();closeModal()});}
function validBackup(s){if(!s||s.version!==1||typeof s.name!=='string'||s.name.length>30||typeof s.avatar!=='string'||s.avatar.length>16)throw Error('备份格式不正确');for(const key of ['habits','rewards','ledger','checks','orders'])if(!Array.isArray(s[key])||s[key].length>100000)throw Error('备份格式不正确');const str=(x,max=120)=>typeof x==='string'&&x.length<=max;const integer=n=>Number.isSafeInteger(n)&&n>0&&n<=1000000;for(const h of s.habits)if(!str(h.id)||!str(h.name,30)||!str(h.icon,16)||!integer(h.points)||!['学习成长','家务劳动','生活习惯'].includes(h.category)||!str(h.note||''))throw Error('习惯数据不正确');for(const r of s.rewards)if(!str(r.id)||!str(r.name,30)||!str(r.icon,16)||!integer(r.cost)||!['cash','reward'].includes(r.type)||!str(r.note||''))throw Error('奖励数据不正确');const validDate=d=>str(d)&&!isNaN(new Date(d).getTime());for(const e of s.ledger)if(!str(e.id)||!str(e.title)||!Number.isSafeInteger(e.amount)||Math.abs(e.amount)>1000000||!validDate(e.at)||!['habit','redeem','refund','adjust'].includes(e.kind))throw Error('积分明细不正确');if(!Number.isSafeInteger(balance(s))||balance(s)<0)throw Error('积分余额不正确');for(const o of s.orders)if(!str(o.id)||!str(o.title)||!str(o.icon,16)||!integer(o.cost)||!validDate(o.at)||!['cash','reward'].includes(o.type)||!['pending','fulfilled','cancelled'].includes(o.status))throw Error('兑换记录不正确');for(const c of s.checks)if(!str(c.habitId)||!/^\d{4}-\d{2}-\d{2}$/.test(c.day))throw Error('打卡记录不正确');for(const arr of [s.habits,s.rewards,s.ledger,s.orders])if(new Set(arr.map(x=>x.id)).size!==arr.length)throw Error('备份包含重复记录');for(const x of [...s.habits,...s.rewards,...s.orders])if(!/^[a-zA-Z0-9-]+$/.test(x.id))throw Error('记录标识不正确');return s;}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const {action,id}=target.dataset;try{switch(action){case 'nav':page=target.dataset.page;menu=false;render();window.scrollTo(0,0);break;case 'menu':menu=!menu;render();break;case 'filter':filter=target.dataset.filter;render();break;case 'ledger-filter':ledgerFilter=target.dataset.filter;render();break;case 'check':{let points;commit(s=>{points=checkHabit(s,id)});toast(`太棒啦！完成一个好习惯，+${points} 积分 🌱`);break;}case 'add-habit':editHabit();break;case 'edit-habit':editHabit(id);break;case 'add-reward':editReward();break;case 'edit-reward':editReward(id);break;case 'manage-habits':guard(()=>{page='parent';render()});break;case 'unlock':pinModal();break;case 'lock':parent=false;render();toast('家长管理已锁定');break;case 'change-pin':guard(()=>pinModal(()=>toast('家长口令已修改'),true));break;case 'adjust':adjustModal();break;case 'redeem':redeemModal(id);break;case 'close':closeModal();break;case 'emoji':$('#f-icon').value=target.dataset.emoji;break;case 'delete-habit':case 'delete-reward':guard(()=>{const key=action==='delete-habit'?'habits':'rewards';const item=state[key].find(x=>x.id===id);confirmModal('删除'+(key==='habits'?'习惯':'奖励'),`确定删除“${esc(item.name)}”吗？已有打卡、积分及兑换记录仍会保留。`,()=>{commit(s=>s[key]=s[key].filter(x=>x.id!==id));toast('已删除')},'确认删除')});break;case 'fulfill':guard(()=>{const o=state.orders.find(x=>x.id===id);confirmModal(o.type==='cash'?'确认现金已支付':'确认奖励已兑现',o.type==='cash'?`请确认你已经向孩子支付 <strong>¥${o.cost}</strong>。此操作只记录已支付状态，不会转账或再次扣除积分。`:`请确认已为孩子兑现“${esc(o.title)}”。积分在兑换时已扣除。`,()=>{commit(s=>fulfill(s,id));toast('兑现成功，收获一份快乐 💛')},o.type==='cash'?'我已完成支付':'我已兑现奖励')});break;case 'cancel-order':guard(()=>{const o=state.orders.find(x=>x.id===id);confirmModal('取消兑换并退回积分',`取消“${esc(o.title)}”后，将退回 ${o.cost} 积分。`,()=>{commit(s=>cancel(s,id));toast('兑换已取消，积分已退回')},'取消兑换并退分')});break;case 'profile':guard(()=>modal('我的成长名片',`${field('孩子昵称','name',state.name,'text','required maxlength="20"')}${emojiField(state.avatar)}${submit('保存名片')}`,f=>{if(!f.get('name').trim()||!f.get('icon').trim())throw Error('请填写昵称和头像');commit(s=>{s.name=f.get('name').trim();s.avatar=f.get('icon').trim()});closeModal();toast('成长名片已更新')}));break;case 'export':guard(()=>{const {pin,...data}=state;const blob=new Blob([JSON.stringify({...data,pin:null},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`小小成长家-备份-${day}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出，不包含家长口令')});break;case 'import':guard(()=>modal('导入成长备份',`<p>导入会替换当前浏览器的全部成长记录，保留当前家长口令。建议先导出当前数据。</p><div class="field"><label for="f-file">选择备份 JSON 文件</label><input type="file" id="f-file" name="file" accept=".json,application/json" required></div><label class="checkbox-line"><input type="checkbox" required>我确认用备份替换当前数据</label>${submit('导入并替换')}`,async f=>{const file=f.get('file');if(file.size>10000000)throw Error('备份文件不能超过 10 MB');const imported=validBackup(JSON.parse(await file.text()));commit(s=>{const pin=s.pin;Object.assign(s,imported);s.pin=pin});closeModal();toast('成长数据已恢复')}));break;}}catch(error){toast(error.message)}});
document.addEventListener('keydown',e=>{const dialog=$('.modal');if(!dialog)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const list=[...dialog.querySelectorAll('button,input,select')].filter(x=>!x.disabled);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
window.addEventListener('storage',e=>{if(e.key===KEY){try{if(e.newValue){state=JSON.parse(e.newValue);parent=false;closeModal();render();toast('已同步此浏览器其他页面的数据')}}catch{toast('数据读取失败，请重新打开页面')}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&day!==localDay())render()});
setInterval(()=>{if(day!==localDay())render()},30000);
render();if(storageError)toast('未能读取原有数据。请先检查浏览器存储或导入备份。');
